CREATE TABLE "FixedAsset" ("id" TEXT PRIMARY KEY,"entityId" TEXT NOT NULL REFERENCES "Entity"("id") ON DELETE CASCADE,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"acquisitionDate" TIMESTAMP(3) NOT NULL,"inServiceDate" TIMESTAMP(3) NOT NULL,"grossValue" INTEGER NOT NULL,"salvageValue" INTEGER NOT NULL DEFAULT 0,"usefulLifeMonths" INTEGER NOT NULL,"method" TEXT NOT NULL DEFAULT 'STRAIGHT_LINE',"assetAccountCode" TEXT NOT NULL,"depreciationAccountCode" TEXT NOT NULL,"expenseAccountCode" TEXT NOT NULL,"accumulatedDepreciation" INTEGER NOT NULL DEFAULT 0,"bookValue" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'IN_SERVICE',"costCenterCode" TEXT,"supportingDocumentReference" TEXT NOT NULL,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("entityId","code"));
CREATE INDEX "FixedAsset_entityId_status_inServiceDate_idx" ON "FixedAsset"("entityId","status","inServiceDate");
CREATE TABLE "FinancialProvision" ("id" TEXT PRIMARY KEY,"entityId" TEXT NOT NULL REFERENCES "Entity"("id") ON DELETE CASCADE,"code" TEXT NOT NULL,"description" TEXT NOT NULL,"nature" TEXT NOT NULL,"period" TEXT NOT NULL,"amount" INTEGER NOT NULL,"expenseAccountCode" TEXT NOT NULL,"provisionAccountCode" TEXT NOT NULL,"costCenterCode" TEXT,"supportingDocumentReference" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdByUserId" TEXT NOT NULL,"approvedByUserId" TEXT,"postedJournalEntryId" TEXT UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"approvedAt" TIMESTAMP(3),"postedAt" TIMESTAMP(3),UNIQUE("entityId","code"));
CREATE INDEX "FinancialProvision_entityId_period_status_idx" ON "FinancialProvision"("entityId","period","status");
CREATE TABLE "AnalyticalAllocationRule" ("id" TEXT PRIMARY KEY,"entityId" TEXT NOT NULL REFERENCES "Entity"("id") ON DELETE CASCADE,"countryCode" TEXT NOT NULL,"documentType" TEXT NOT NULL,"naturePattern" TEXT NOT NULL,"accountCode" TEXT NOT NULL,"costCenterCode" TEXT NOT NULL,"percentage" DOUBLE PRECISION NOT NULL,"priority" INTEGER NOT NULL DEFAULT 100,"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"updatedByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "AnalyticalAllocationRule_entityId_countryCode_documentType_isActive_priority_idx" ON "AnalyticalAllocationRule"("entityId","countryCode","documentType","isActive","priority");
